    public:
        string name;
        int priority;
        Task(string n, int p) { name = n; priority = p; }
};

vector<Task> v = { Task("a", 5), Task("b", 1) };
sort(v.begin(), v.end());

template <typename T>
class Box {
    private:
        T item;
    public:
        Box(T v) { item = v; }
        T get() const { return item; }
};

int main() {
    Box<int> a(42);
    Box<string> b("hi");
    cout << a.get() << " " << b.get();
}
